const $ = (id) => document.getElementById(id);
const state = {
  pubkey: localStorage.getItem('oc_pubkey') || '',
  signer: localStorage.getItem('oc_signer') || '',
  config: null,
  publication: null,
  articles: [],
  episodes: [],
  crossposts: [],
  analyticsRanges: {},
  analyticsRange: '1d',
  installPrompt: null,
  lastCrossPreviews: {}
};

function setResult(id, message, ok = true) {
  const el = $(id); if (!el) return;
  el.textContent = message; el.className = `result ${ok ? 'ok' : 'error'}`;
}
function toast(message) {
  const el = $('toast'); el.textContent = message; el.classList.add('show');
  setTimeout(() => el.classList.remove('show'), 2600);
}
function shortKey(k) { return k ? `${k.slice(0,8)}…${k.slice(-8)}` : 'Disconnected'; }
function now() { return Math.floor(Date.now()/1000); }
function hex(buf) { return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2,'0')).join(''); }
async function sha256Bytes(data) { return hex(await crypto.subtle.digest('SHA-256', data)); }
async function sha256Text(text) { return sha256Bytes(new TextEncoder().encode(text)); }
function b64Json(obj) { const bytes=new TextEncoder().encode(JSON.stringify(obj)); let binary=''; for(const b of bytes)binary+=String.fromCharCode(b); return btoa(binary); }
function slugify(s) { return s.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,160); }
function cleanLines(text) { return String(text||'').split(/\n|,/).map(s=>s.trim()).filter(Boolean); }
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function currentRelays(){const relays=cleanLines($('pubRelays').value);return relays.length?relays:(state.config?.defaultRelays||[]);}
function currentBlossom(){return($('pubBlossom').value||state.config?.defaultBlossom||'').replace(/\/$/,'');}
function selectedTargets(){return[['bluesky','targetBluesky'],['mastodon','targetMastodon'],['x','targetX']].filter(([,id])=>$(id).checked).map(([t])=>t);}
function currentPublicationBody(){return{title:$('pubTitle').value,description:$('pubDescription').value,website:$('pubWebsite').value,cover:$('pubCover').value,blossom:currentBlossom(),relays:currentRelays(),podcast:$('pubPodcast').checked,discoverable:$('pubDiscoverable').checked,language:$('pubLanguage').value,categories:cleanLines($('pubCategories').value),xmrAddress:$('xmrAddress').value.trim(),xmrChatUrl:$('xmrChatUrl').value.trim()};}

async function computeEventId(unsigned,pubkey){return sha256Text(JSON.stringify([0,pubkey,unsigned.created_at,unsigned.kind,unsigned.tags,unsigned.content]));}
async function parseSignerEvent(raw,pending){let value=raw;try{value=decodeURIComponent(value)}catch{}if(value.startsWith('{')){const ev=JSON.parse(value);const u=pending.unsigned;if(!ev||ev.kind!==u.kind||ev.created_at!==u.created_at||ev.content!==u.content||JSON.stringify(ev.tags)!==JSON.stringify(u.tags))throw new Error('Signer returned a different event than the one requested');return ev;}if(/^[0-9a-f]{128}$/i.test(value)){const pubkey=pending.pubkey;return{...pending.unsigned,pubkey,sig:value.toLowerCase(),id:await computeEventId(pending.unsigned,pubkey)};}throw new Error('Signer did not return a signed event');}

async function startSign(unsigned,continuation){
  if(!state.pubkey)throw new Error('Connect a Nostr identity first');
  if(state.signer==='demo'){
    const res=await fetch('/api/test/sign',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({unsigned})});
    const signed=await res.json(); if(!res.ok)throw new Error(signed.error||'Demo signer failed');
    return handleSigned(signed,continuation);
  }
  if(window.nostr&&state.signer!=='nip55'){const signed=await window.nostr.signEvent(unsigned);return handleSigned(signed,continuation);}
  if(state.signer==='nip55'){
    localStorage.setItem('oc_pending_sign',JSON.stringify({unsigned,continuation,pubkey:state.pubkey}));
    const callback=`${location.origin}${location.pathname}?nip55event=`;
    location.href=`nostrsigner:${encodeURIComponent(JSON.stringify(unsigned))}?compressionType=none&returnType=event&type=sign_event&callbackUrl=${encodeURIComponent(callback)}`;
    return;
  }
  throw new Error('No compatible signer detected');
}

async function publishToRelay(relay,event){return new Promise(resolve=>{let settled=false,ws;const finish=(ok,message='')=>{if(settled)return;settled=true;try{ws?.close()}catch{}resolve({relay,ok,message});};try{ws=new WebSocket(relay)}catch(e){return finish(false,e.message)}const timer=setTimeout(()=>finish(false,'timeout'),4500);ws.onopen=()=>ws.send(JSON.stringify(['EVENT',event]));ws.onmessage=(msg)=>{try{const d=JSON.parse(msg.data);if(d[0]==='OK'&&d[1]===event.id){clearTimeout(timer);finish(Boolean(d[2]),d[3]||'')}}catch{}};ws.onerror=()=>{clearTimeout(timer);finish(false,'connection error')}});}
async function publishRelays(event){const relays=currentRelays();return relays.length?Promise.all(relays.map(r=>publishToRelay(r,event))):[];}
async function authenticatedRequest(method,path,payloadObj,meta={}){const body=payloadObj==null?'':JSON.stringify(payloadObj);const tags=[['u',`${location.origin}${path}`],['method',method.toUpperCase()]];if(['POST','PUT','PATCH','DELETE'].includes(method.toUpperCase()))tags.push(['payload',await sha256Text(body)]);return startSign({kind:27235,created_at:now(),content:'',tags},{type:'apiRequest',method,path,body,...meta});}

async function handleSigned(signed,c){
  if(!signed?.id||!signed?.sig||!signed?.pubkey)throw new Error('Signer returned an incomplete event');
  if(signed.pubkey!==state.pubkey)throw new Error('Signer returned a different public key');
  if(c.type==='apiRequest'){
    const res=await fetch(c.path,{method:c.method,headers:{'content-type':'application/json','authorization':`Nostr ${b64Json(signed)}`},body:c.body||undefined});
    const data=await res.json().catch(()=>({error:`HTTP ${res.status}`})); if(!res.ok)throw new Error(data.error||`HTTP ${res.status}`);
    if(c.resultTarget)setResult(c.resultTarget,c.successMessage||'Saved');
    if(c.after==='publication'){await loadPublication();await refreshAll();}
    if(c.after==='article'){setResult('articleResult',`Published: ${data.slug}`);await refreshAll();}
    if(c.after==='episode'){setResult('episodeResult',`Episode published: ${data.title}`);await refreshAll();}
    if(c.after==='crossPreview'){state.lastCrossPreviews=data.previews||{};renderCrossPreviews(data.previews||{});setResult('crossResult','Previews generated.');}
    if(c.after==='crossSim'){setResult('crossResult',`Queued test job ${data.id} (${data.targets.join(', ')})`);await refreshAll();}
    if(c.after==='analytics'){state.analyticsRanges=data.ranges||{};renderAnalytics();setResult('insightsResult','Insights refreshed.');}
    if(c.after==='seedAnalytics'){state.analyticsRanges=data.ranges||{};renderAnalytics();setResult('insightsResult','Synthetic privacy-safe demo data added.');}
    return data;
  }
  if(c.type==='articleEvent'){
    setResult('articleResult','Signed. Publishing to relays…');const rr=await publishRelays(signed);const ok=rr.filter(x=>x.ok).length;setResult('articleResult',`Relay acceptance ${ok}/${rr.length}. Saving hosted copy…`,ok>0||rr.length===0);return authenticatedRequest('POST','/api/articles',{event:signed},{after:'article'});
  }
  if(c.type==='episodeEvent'){
    setResult('episodeResult','Signed. Publishing episode…');const rr=await publishRelays(signed);const ok=rr.filter(x=>x.ok).length;setResult('episodeResult',`Relay acceptance ${ok}/${rr.length}. Updating RSS…`,ok>0||rr.length===0);return authenticatedRequest('POST','/api/episodes',{event:signed},{after:'episode'});
  }
  if(c.type==='podcastMeta'){const rr=await publishRelays(signed);const ok=rr.filter(x=>x.ok).length;setResult('publicationResult',`Podcast metadata sent to ${ok}/${rr.length} relays.`,ok>0||rr.length===0);return;}
  if(c.type==='blossomUpload'){
    const record=await idbGet(c.fileKey);if(!record?.blob)throw new Error('Pending upload file unavailable');setResult('mediaResult','Authorized. Uploading to Blossom…');
    const res=await fetch(`${c.server}/upload`,{method:'PUT',headers:{Authorization:`Nostr ${b64Json(signed)}`,'Content-Type':record.type||'application/octet-stream'},body:record.blob});
    const data=await res.json().catch(async()=>({error:await res.text().catch(()=>`HTTP ${res.status}`)}));if(!res.ok)throw new Error(data.error||data.message||`Blossom HTTP ${res.status}`);await idbDelete(c.fileKey);const url=data.url||`${c.server}/${c.hash}`;$('episodeAudio').value=url;setResult('mediaResult',`Uploaded: ${url}`);toast('Audio URL copied into Podcast');
  }
}

function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('opencast-publisher',1);req.onupgradeneeded=()=>req.result.createObjectStore('pending');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});}
async function idbPut(key,value){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction('pending','readwrite');tx.objectStore('pending').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});}
async function idbGet(key){const db=await openDb();return new Promise((resolve,reject)=>{const r=db.transaction('pending').objectStore('pending').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});}
async function idbDelete(key){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction('pending','readwrite');tx.objectStore('pending').delete(key);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});}

async function loginNip07(){if(!window.nostr)throw new Error('No NIP-07 browser signer found');const pubkey=await window.nostr.getPublicKey();if(!/^[0-9a-f]{64}$/i.test(pubkey))throw new Error('Signer returned invalid pubkey');setIdentity(pubkey.toLowerCase(),'nip07');await onConnected();}
function loginNip55(){localStorage.setItem('oc_pending_login',String(Date.now()));const callback=`${location.origin}${location.pathname}?nip55pub=`;location.href=`nostrsigner:?type=get_public_key&callbackUrl=${encodeURIComponent(callback)}`;}
async function loginDemo(){if(!state.config?.testMode)throw new Error('Test mode is disabled');setIdentity(state.config.demoPubkey,'demo');await onConnected();toast('Connected to disposable test identity');}
function setIdentity(pubkey,signer){state.pubkey=pubkey;state.signer=signer;localStorage.setItem('oc_pubkey',pubkey);localStorage.setItem('oc_signer',signer);}
async function processNip55Return(){const u=new URL(location.href);const pub=u.searchParams.get('nip55pub');if(pub){const asked=Number(localStorage.getItem('oc_pending_login')||0);localStorage.removeItem('oc_pending_login');if(!asked||Date.now()-asked>600000){history.replaceState({},'',location.pathname);throw new Error('Ignored a sign-in link that this browser did not request');}if(!/^[0-9a-f]{64}$/i.test(pub))throw new Error('Android signer returned invalid public key');setIdentity(pub.toLowerCase(),'nip55');history.replaceState({},'',location.pathname);}const returned=u.searchParams.get('nip55event');if(returned){const raw=localStorage.getItem('oc_pending_sign');if(!raw)throw new Error('No pending signer request found');const pending=JSON.parse(raw);const signed=await parseSignerEvent(returned,pending);localStorage.removeItem('oc_pending_sign');history.replaceState({},'',location.pathname);await handleSigned(signed,pending.continuation);}}

async function onConnected(){
  $('identityBox').classList.toggle('connected',Boolean(state.pubkey));$('identityText').textContent=state.pubkey?`${state.signer} · ${shortKey(state.pubkey)}`:'Not connected';$('statusIdentity').textContent=state.pubkey?`${state.signer.toUpperCase()} · ${shortKey(state.pubkey)}`:'Disconnected';$('loginBtn').textContent=state.pubkey?'Reconnect signer':'Connect Nostr';
  if(state.pubkey){await loadPublication();await refreshAll();}
}
async function loadPublication(){if(!state.pubkey)return;const res=await fetch(`/api/publication/${state.pubkey}`);if(res.ok){state.publication=await res.json();const p=state.publication;$('pubTitle').value=p.title||'';$('pubDescription').value=p.description||'';$('pubWebsite').value=p.website||'';$('pubCover').value=p.cover||'';$('pubBlossom').value=p.blossom||state.config.defaultBlossom;$('pubRelays').value=(p.relays||state.config.defaultRelays).join('\n');$('pubPodcast').checked=Boolean(p.podcast);$('pubDiscoverable').checked=p.discoverable!==false;$('pubLanguage').value=p.language||'en';$('pubCategories').value=(p.categories||[]).join(', ');$('xmrAddress').value=p.xmrAddress||'';$('xmrChatUrl').value=p.xmrChatUrl||'';$('statusSite').textContent='Online';$('statusRss').textContent=p.podcast?'Enabled':'Disabled';$('statusXmr').textContent=(p.xmrAddress||p.xmrChatUrl)?'Enabled':'Not configured';$('mediaStatus').textContent='Ready';$('rssLink').href=`/rss/${state.pubkey}.xml`;$('siteLink').href=`/p/${state.pubkey}`;$('tipPageLink').href=`/p/${state.pubkey}/tip`;}else{state.publication=null;$('pubBlossom').value=state.config.defaultBlossom;$('pubRelays').value=state.config.defaultRelays.join('\n');$('statusSite').textContent='Not configured';$('statusRss').textContent='Not configured';$('statusXmr').textContent='Not configured';$('mediaStatus').textContent='Setup needed';}}
async function refreshAll(){if(!state.pubkey)return;const[a,e,c]=await Promise.all([fetch(`/api/articles/${state.pubkey}`).then(r=>r.ok?r.json():[]),fetch(`/api/episodes/${state.pubkey}`).then(r=>r.ok?r.json():[]),fetch(`/api/crossposts/${state.pubkey}`).then(r=>r.ok?r.json():[])]);state.articles=a;state.episodes=e;state.crossposts=c;$('articleCount').textContent=a.length;$('episodeCount').textContent=e.length;$('crosspostCount').textContent=c.length;populateCrossSources();}
function populateCrossSources(){const sel=$('crossSource');const current=sel.value;sel.innerHTML='';const options=[];for(const a of state.articles)options.push({value:`article:${a.eventId||a.slug}`,label:`Article · ${a.title||a.slug}`});for(const e of state.episodes){const title=(e.tags||[]).find(t=>t[0]==='title')?.[1]||'Episode';options.push({value:`episode:${e.id}`,label:`Podcast · ${title}`});}if(!options.length){sel.innerHTML='<option value="">Publish something first</option>';return;}for(const o of options){const opt=document.createElement('option');opt.value=o.value;opt.textContent=o.label;sel.appendChild(opt);}if(options.some(o=>o.value===current))sel.value=current;}

async function savePublication(resultTarget='publicationResult'){const body=currentPublicationBody();if(!body.title.trim())throw new Error('Publication name is required');setResult(resultTarget,'Waiting for signer authorization…');return authenticatedRequest('PUT','/api/publication',body,{resultTarget,successMessage:'Publication saved.',after:'publication'});}
async function publishPodcastMetadata(){if(!$('pubTitle').value.trim())throw new Error('Configure the publication first');const tags=[['title',$('pubTitle').value.trim()],['description',$('pubDescription').value.trim()]];if($('pubCover').value.trim())tags.push(['image',$('pubCover').value.trim()]);if($('pubWebsite').value.trim())tags.push(['website',$('pubWebsite').value.trim()]);tags.push(['p',state.pubkey,'host']);return startSign({kind:10154,created_at:now(),content:'',tags},{type:'podcastMeta'});}
async function publishArticle(){const title=$('articleTitle').value.trim();if(!title)throw new Error('Article title required');const slug=$('articleSlug').value.trim()||slugify(title);const tags=[['d',slug],['title',title],['summary',$('articleSummary').value.trim()],['published_at',String(now())]];if($('articleImage').value.trim())tags.push(['image',$('articleImage').value.trim()]);for(const t of cleanLines($('articleTopics').value))tags.push(['t',t.toLowerCase()]);setResult('articleResult','Waiting for signer…');return startSign({kind:30023,created_at:now(),content:$('articleBody').value,tags},{type:'articleEvent'});}
async function publishEpisode(){const title=$('episodeTitle').value.trim(),audio=$('episodeAudio').value.trim();if(!title||!audio)throw new Error('Episode title and audio URL required');const tags=[['title',title],['description',$('episodeDescription').value.trim()],['audio',audio,$('episodeMime').value]];if($('pubCover').value.trim())tags.push(['image',$('pubCover').value.trim()]);setResult('episodeResult','Waiting for signer…');return startSign({kind:54,created_at:now(),content:$('episodeBody').value,tags},{type:'episodeEvent'});}
async function uploadMedia(){const file=$('mediaFile').files?.[0];if(!file)throw new Error('Choose a file first');const server=currentBlossom();if(!server)throw new Error('Configure a Blossom server first');const bytes=await file.arrayBuffer();const hash=await sha256Bytes(bytes);const key=`upload-${Date.now()}-${hash.slice(0,12)}`;await idbPut(key,{blob:file,type:file.type,name:file.name});const host=new URL(server).hostname;const auth={kind:24242,created_at:now(),content:'Authorize upload',tags:[['t','upload'],['expiration',String(now()+300)],['x',hash],['server',host]]};setResult('mediaResult',`SHA-256 ${hash.slice(0,16)}… Waiting for signer…`);return startSign(auth,{type:'blossomUpload',fileKey:key,server,hash});}


const COUNTRY_POINTS={US:[38,-97],CA:[56,-106],MX:[23,-102],BR:[-10,-52],AR:[-34,-64],GB:[54,-2],IE:[53,-8],FR:[46,2],DE:[51,10],NL:[52,5],ES:[40,-4],IT:[42,12],SE:[62,15],NO:[62,10],PL:[52,19],UA:[49,32],IS:[65,-19],JP:[36,138],KR:[36,128],IN:[21,79],SG:[1,104],AU:[-25,134],NZ:[-41,174],ZA:[-30,25],NG:[9,8],KE:[1,38]};
function fmtNum(n){return new Intl.NumberFormat().format(Number(n||0));}
function rankRows(rootId,obj,total){const root=$(rootId);root.innerHTML='';const rows=Object.entries(obj||{}).sort((a,b)=>b[1]-a[1]).slice(0,8);if(!rows.length){root.innerHTML='<p class="muted">No data yet.</p>';return;}for(const [name,count] of rows){const pct=total?Math.round(count/total*100):0;const row=document.createElement('div');row.className='rank-row';row.innerHTML=`<div><strong>${esc(name)}</strong><small>${fmtNum(count)} · ${pct}%</small></div><span></span>`;row.lastElementChild.style.setProperty('--pct',`${Math.max(4,pct)}%`);root.appendChild(row);}}
function renderBarChart(series=[]){const root=$('analyticsChart');root.innerHTML='';const data=series.slice(-60);if(!data.length){root.innerHTML='<p class="muted">No activity yet.</p>';return;}const max=Math.max(1,...data.map(x=>x.count||0));for(const x of data){const bar=document.createElement('div');bar.className='bar';bar.style.height=`${Math.max(4,Math.round((x.count||0)/max*100))}%`;bar.title=`${x.day}: ${fmtNum(x.count)}`;root.appendChild(bar);}}
function renderWorldMap(countries={}){const plot=$('analyticsMapPlot');plot.innerHTML='';const total=Object.values(countries).reduce((a,b)=>a+b,0);for(const [code,count] of Object.entries(countries)){if(code==='Other'||!COUNTRY_POINTS[code])continue;const [lat,lon]=COUNTRY_POINTS[code];const dot=document.createElement('button');dot.className='map-dot';dot.style.left=`${(lon+180)/360*100}%`;dot.style.top=`${(90-lat)/180*100}%`;dot.style.setProperty('--size',`${Math.min(24,8+Math.sqrt(count)*2)}px`);dot.title=`${code}: ${fmtNum(count)}`;dot.setAttribute('aria-label',dot.title);plot.appendChild(dot);}const list=$('analyticsCountries');list.innerHTML='';for(const [code,count] of Object.entries(countries).sort((a,b)=>b[1]-a[1]).slice(0,10)){const d=document.createElement('div');d.innerHTML=`<strong>${esc(code)}</strong><span>${fmtNum(count)}${total?` · ${Math.round(count/total*100)}%`:''}</span>`;list.appendChild(d);}}
function renderAnalytics(range=state.analyticsRange){state.analyticsRange=range;const r=state.analyticsRanges?.[range]||{count:0,series:[],countries:{},clients:{},referrers:{},items:[]};$('insight1d').textContent=fmtNum(state.analyticsRanges?.['1d']?.count||0);$('insight7d').textContent=fmtNum(state.analyticsRanges?.['7d']?.count||0);$('insight30d').textContent=fmtNum(state.analyticsRanges?.['30d']?.count||0);$('insightLifetime').textContent=fmtNum(state.analyticsRanges?.lifetime?.count||0);document.querySelectorAll('.range').forEach(b=>b.classList.toggle('active',b.dataset.range===range));$('chartRangeLabel').textContent=range==='1d'?'24 hours':range==='7d'?'7 days':range==='30d'?'30 days':'Lifetime';renderBarChart(r.series||[]);rankRows('analyticsClients',r.clients||{},r.count||0);rankRows('analyticsReferrers',r.referrers||{},r.count||0);renderWorldMap(r.countries||{});const items=$('analyticsItems');items.innerHTML='';for(const item of (r.items||[]).slice(0,8)){const row=document.createElement('div');row.className='rank-item';row.innerHTML=`<span><small>${esc(item.type||'content')}</small><strong>${esc(item.title||item.id)}</strong></span><b>${fmtNum(item.count)}</b>`;items.appendChild(row);}if(!(r.items||[]).length)items.innerHTML='<p class="muted">No content activity yet.</p>';}
async function loadAnalytics(){if(!state.pubkey)throw new Error('Connect a Nostr identity first');setResult('insightsResult','Requesting private aggregate insights…');return authenticatedRequest('GET','/api/analytics?range=all',null,{after:'analytics'});}
async function seedAnalytics(){if(!state.config?.testMode)throw new Error('Demo seeding is available only in test mode');setResult('insightsResult','Generating synthetic aggregate data…');return authenticatedRequest('POST','/api/test/analytics/seed',{}, {after:'seedAnalytics'});}

function renderDiscover(results,append=false){const root=$('discoverCards');if(!append)root.innerHTML='';for(const item of results){const card=document.createElement('article');card.className='card';const rawUrl=String(item.url||'');const url=/^https?:\/\//i.test(rawUrl)||(rawUrl.startsWith('/')&&!rawUrl.startsWith('//'))?rawUrl:'#';card.innerHTML=`<div class="card-head"><div><span class="tag">${esc(item.type||'result')}</span><h3>${esc(item.title||'Untitled')}</h3></div></div><p>${esc(item.summary||'')}</p><small>${esc((item.categories||[]).join(' · '))}</small><div class="actions"><a class="button ghost" href="${esc(url)}" ${String(url).startsWith('http')?'target="_blank" rel="noreferrer"':''}>Open</a></div>`;root.appendChild(card);}}
async function discoverLocal(){const q=$('discoverQuery').value.trim(),type=$('discoverType').value;setResult('discoverResult','Searching hosted index…');const data=await fetch(`/api/discover?q=${encodeURIComponent(q)}&type=${encodeURIComponent(type)}`).then(r=>r.json());renderDiscover(data.results||[]);setResult('discoverResult',`${(data.results||[]).length} hosted result(s).`);}
async function queryNip50Relay(relay,q){return new Promise(resolve=>{const out=[];let ws;const sub=`search-${Math.random().toString(36).slice(2)}`;const finish=()=>{try{ws?.send(JSON.stringify(['CLOSE',sub]));ws?.close()}catch{}resolve(out)};try{ws=new WebSocket(relay)}catch{return resolve(out)}const timer=setTimeout(finish,4200);ws.onopen=()=>ws.send(JSON.stringify(['REQ',sub,{kinds:[30023,54],search:q,limit:10}]));ws.onmessage=e=>{try{const m=JSON.parse(e.data);if(m[0]==='EVENT'&&m[1]===sub){const ev=m[2];const tag=n=>(ev.tags||[]).find(t=>t[0]===n)?.[1]||'';out.push({type:ev.kind===54?'nostr podcast':'nostr article',title:tag('title')||tag('name')||'Nostr result',summary:tag('summary')||tag('description')||String(ev.content||'').slice(0,220),categories:(ev.tags||[]).filter(t=>t[0]==='t').map(t=>t[1]).slice(0,5),url:`https://njump.me/${ev.id}`});}if(m[0]==='EOSE'&&m[1]===sub){clearTimeout(timer);finish();}}catch{}};ws.onerror=()=>{clearTimeout(timer);finish()};});}
async function discoverNostr(){const q=$('discoverQuery').value.trim();if(!q)throw new Error('Enter a search first');const relays=currentRelays().slice(0,4);setResult('discoverResult',`Querying ${relays.length} relay(s) with NIP-50…`);const batches=await Promise.all(relays.map(r=>queryNip50Relay(r,q)));const seen=new Set(),all=[];for(const b of batches)for(const x of b){const key=x.title+'|'+x.summary;if(!seen.has(key)){seen.add(key);all.push(x)}}renderDiscover(all,true);setResult('discoverResult',`Added ${all.length} relay result(s).`);}
async function discoverPodcastIndex(){const q=$('discoverQuery').value.trim();if(!q)throw new Error('Enter a search first');setResult('discoverResult','Searching Podcast Index…');const res=await fetch(`/api/discover/podcastindex?q=${encodeURIComponent(q)}`);const data=await res.json();if(!res.ok)throw new Error(data.error||'Podcast Index search failed');renderDiscover(data.results||[],true);setResult('discoverResult',`Added ${(data.results||[]).length} Podcast Index result(s).`);}

function sourceParts(){const v=$('crossSource').value;if(!v)return null;const i=v.indexOf(':');return{sourceType:v.slice(0,i),sourceId:v.slice(i+1)};}
async function crossPreview(){const source=sourceParts();if(!source)throw new Error('Choose published content');const targets=selectedTargets();if(!targets.length)throw new Error('Choose at least one target');setResult('crossResult','Generating network-specific previews…');return authenticatedRequest('POST','/api/crosspost/preview',{...source,targets},{after:'crossPreview'});}
function renderCrossPreviews(previews){const root=$('crossCards');root.innerHTML='';for(const [target,body] of Object.entries(previews)){const card=document.createElement('article');card.className='card';const canCompose=target==='bluesky'||target==='x';const composeUrl=target==='bluesky'?`https://bsky.app/intent/compose?text=${encodeURIComponent(body)}`:`https://x.com/intent/post?text=${encodeURIComponent(body)}`;card.innerHTML=`<span class="tag">${esc(target)}</span><div class="pretext">${esc(body)}</div><div class="actions"><button class="button ghost copy-cross" data-target="${esc(target)}">Copy</button>${canCompose?`<a class="button secondary" target="_blank" rel="noreferrer" href="${esc(composeUrl)}">Open compose</a>`:''}</div>`;root.appendChild(card);}root.querySelectorAll('.copy-cross').forEach(b=>b.addEventListener('click',async()=>{await navigator.clipboard.writeText(state.lastCrossPreviews[b.dataset.target]||'');toast('Copied')}));}
async function crossSimulate(){const source=sourceParts();if(!source)throw new Error('Choose published content');const targets=selectedTargets();if(!targets.length)throw new Error('Choose at least one target');return authenticatedRequest('POST','/api/crosspost/simulate',{...source,targets},{after:'crossSim'});}

function fillDemo(){
  $('pubTitle').value='Privacy Signal';$('pubDescription').value='Independent privacy, Monero and open-protocol publishing.';$('pubLanguage').value='en';$('pubCategories').value='privacy, monero, nostr, technology';$('pubPodcast').checked=true;$('pubDiscoverable').checked=true;
  $('articleTitle').value='Why creator-owned publishing matters';$('articleSlug').value='creator-owned-publishing';$('articleSummary').value='A short test article showing how OpenCast keeps publication identity portable.';$('articleTopics').value='nostr, privacy, publishing';$('articleBody').value='# Creator-owned publishing\n\nThis is sample content for the OpenCast test build. Sign it with the disposable test identity, publish it to selected relays, and keep a hosted copy.';
  $('episodeTitle').value='OpenCast Test Episode';$('episodeDescription').value='A sample podcast entry for testing RSS, Nostr metadata, discovery and cross-post previews.';$('episodeAudio').value='https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3';$('episodeBody').value='Testing the complete publishing flow.';toast('Sample forms filled');
}

function bind(){
  document.querySelectorAll('.nav').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.nav,.view').forEach(x=>x.classList.remove('active'));btn.classList.add('active');const v=btn.dataset.view;$(`view-${v}`).classList.add('active');$('viewTitle').textContent=btn.textContent;if(v==='insights'&&state.pubkey&&!Object.keys(state.analyticsRanges).length)loadAnalytics().catch(e=>setResult('insightsResult',e.message,false));}));
  $('loginBtn').addEventListener('click',()=>loginNip07().catch(e=>toast(e.message)));$('androidLoginBtn').addEventListener('click',loginNip55);$('demoBtn').addEventListener('click',()=>loginDemo().catch(e=>toast(e.message)));$('demoFillBtn').addEventListener('click',fillDemo);
  $('savePublicationBtn').addEventListener('click',()=>savePublication().catch(e=>setResult('publicationResult',e.message,false)));$('saveMoneroBtn').addEventListener('click',()=>savePublication('moneroResult').catch(e=>setResult('moneroResult',e.message,false)));$('publishPodcastMetaBtn').addEventListener('click',()=>publishPodcastMetadata().catch(e=>setResult('publicationResult',e.message,false)));$('publishArticleBtn').addEventListener('click',()=>publishArticle().catch(e=>setResult('articleResult',e.message,false)));$('publishEpisodeBtn').addEventListener('click',()=>publishEpisode().catch(e=>setResult('episodeResult',e.message,false)));$('uploadMediaBtn').addEventListener('click',()=>uploadMedia().catch(e=>setResult('mediaResult',e.message,false)));
  $('copyXmrBtn').addEventListener('click',async()=>{const v=$('xmrAddress').value.trim();if(!v)return toast('No Monero address');await navigator.clipboard.writeText(v);toast('Monero address copied')});
  $('refreshInsightsBtn').addEventListener('click',()=>loadAnalytics().catch(e=>setResult('insightsResult',e.message,false)));$('seedInsightsBtn').addEventListener('click',()=>seedAnalytics().catch(e=>setResult('insightsResult',e.message,false)));document.querySelectorAll('.range').forEach(b=>b.addEventListener('click',()=>renderAnalytics(b.dataset.range)));
  $('discoverBtn').addEventListener('click',()=>discoverLocal().catch(e=>setResult('discoverResult',e.message,false)));$('nostrSearchBtn').addEventListener('click',()=>discoverNostr().catch(e=>setResult('discoverResult',e.message,false)));$('podcastIndexBtn').addEventListener('click',()=>discoverPodcastIndex().catch(e=>setResult('discoverResult',e.message,false)));$('discoverQuery').addEventListener('keydown',e=>{if(e.key==='Enter')discoverLocal().catch(err=>setResult('discoverResult',err.message,false))});
  $('crossPreviewBtn').addEventListener('click',()=>crossPreview().catch(e=>setResult('crossResult',e.message,false)));$('crossSimBtn').addEventListener('click',()=>crossSimulate().catch(e=>setResult('crossResult',e.message,false)));
  $('articleTitle').addEventListener('input',()=>{if(!$('articleSlug').dataset.touched)$('articleSlug').value=slugify($('articleTitle').value)});$('articleSlug').addEventListener('input',()=>{$('articleSlug').dataset.touched='1'});$('mediaFile').addEventListener('change',()=>{const f=$('mediaFile').files?.[0];$('mediaFileMeta').textContent=f?`${f.name} · ${(f.size/1024/1024).toFixed(1)} MB`:'No file selected'});
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e;$('installBtn').hidden=false});$('installBtn').addEventListener('click',async()=>{if(state.installPrompt){state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;$('installBtn').hidden=true}});
}

async function boot(){bind();state.config=await fetch('/api/config').then(r=>r.json());if(state.config.testMode){$('testBanner').hidden=false;$('demoBtn').hidden=false;$('demoFillBtn').hidden=false;$('seedInsightsBtn').hidden=false;}if(state.config.podcastIndexEnabled)$('podcastIndexBtn').hidden=false;if(state.signer==='demo'&&!state.config.testMode){localStorage.removeItem('oc_pubkey');localStorage.removeItem('oc_signer');state.pubkey='';state.signer='';}if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});await processNip55Return();await onConnected();await discoverLocal().catch(()=>{});}
boot().catch(e=>{console.error(e);toast(e.message||'Startup failed')});
